if (!$profile) { http_response_code(404); exit('Account not found.'); }
$form=['first_name'=>$profile['first_name']??'','middle_name'=>$profile['middle_name']??'','last_name'=>$profile['last_name']??'','mobileno'=>$profile['mobileno']??''];

function anonymize_customer(PDO $pdo,int $userId,string $email): void {
    $pdo->beginTransaction();
    try {
        $locked=$pdo->prepare('SELECT order_id,status FROM customer_orders WHERE user_id=? FOR UPDATE'); $locked->execute([$userId]); $orders=$locked->fetchAll();
        foreach ($orders as $order) if (!in_array(strtolower((string)$order['status']),['cancelled','completed','delivered','rejected','failed'],true)) throw new DomainException('Your account cannot be deleted while an order is active.');
        $ids=array_map('intval',array_column($orders,'order_id'));
        $pdo->prepare("UPDATE customer_orders SET user_id=NULL,customer_name='Deleted customer',phone='',delivery_address=NULL,delivery_instructions=NULL WHERE user_id=?")->execute([$userId]);
        if ($ids) { $marks=implode(',',array_fill(0,count($ids),'?')); $pdo->prepare("UPDATE customer_order_items SET options_json=JSON_REMOVE(options_json,'$.specialRequest') WHERE order_id IN ($marks) AND options_json IS NOT NULL")->execute($ids); }
        $pdo->prepare('DELETE FROM user_addresses WHERE user_id=?')->execute([$userId]);
        $anon='deleted-'.$userId.'@invalid.local';
        $pdo->prepare('DELETE FROM auth_otp_challenges WHERE user_id=?')->execute([$userId]);
        $pdo->prepare('UPDATE user_credentials SET email_addr=?,password=?,is_active=0 WHERE user_id=?')->execute([$anon,password_hash(bin2hex(random_bytes(32)),PASSWORD_DEFAULT),$userId]);
        $pdo->prepare("UPDATE user_info SET first_name='Deleted',middle_name=NULL,last_name='Customer',home_addr='',mobileno=CONCAT('deleted-',user_id),photo_path=NULL WHERE user_id=?")->execute([$userId]);
        $pdo->commit();
    } catch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); throw $e; }
}

if ($_SERVER['REQUEST_METHOD']==='POST') {
    $action=(string)($_POST['action']??'');
    if (!csrf_check($_POST['csrf']??null)) $errors[]='Session expired. Please try again.';
    elseif ($action==='save') {
        foreach ($form as $key=>$_) $form[$key]=trim((string)($_POST[$key]??''));
        $form['mobileno']=normalize_mobile($form['mobileno']);
        $changed=false; foreach ($form as $key=>$value) if ((string)$value!==(string)($profile[$key]??'')) $changed=true;
        if (!$changed) $success='There are no changes to save.';
        else {
            if (!verify_account_password($pdo,$userId,(string)($_POST['current_password']??''))) $errors[]='Enter your current password to confirm these changes.';
            if (!preg_match(NAME_RE,$form['first_name'])||!preg_match(NAME_RE,$form['last_name'])||($form['middle_name']!==''&&!preg_match(NAME_RE,$form['middle_name']))) $errors[]='Enter valid personal names.';
            if (!preg_match(MOBILE_RE,$form['mobileno'])) $errors[]='Enter a valid Philippine mobile number.';
            if (!$errors) { $dup=$pdo->prepare('SELECT 1 FROM user_info WHERE mobileno=? AND user_id<>?'); $dup->execute([$form['mobileno'],$userId]); if ($dup->fetchColumn()) $errors[]='That mobile number is already in use.'; }
            if (!$errors) { $pdo->prepare('UPDATE user_info SET first_name=?,middle_name=?,last_name=?,mobileno=? WHERE user_id=?')->execute([$form['first_name'],$form['middle_name']?:null,$form['last_name'],$form['mobileno'],$userId]); $_SESSION['first_name']=$form['first_name']; $_SESSION['flash_success']='Personal details updated.'; header('Location: profile.php'); exit; }
        }
    } elseif ($action==='begin_password_change') {
        $newPassword=(string)($_POST['new_password']??''); $confirmPassword=(string)($_POST['confirm_password']??'');
        if (!verify_account_password($pdo,$userId,(string)($_POST['password_current']??''))) $errors[]='Enter your current password to change it.';
        if (!preg_match(PASS_RE,$newPassword)||strlen($newPassword)>72) $errors[]='Use 8 to 72 characters with a lowercase letter, uppercase letter, number, and special character.';
        elseif ($newPassword!==$confirmPassword) $errors[]='The new passwords do not match.';
        if (!$errors) { try { $cid=create_otp_challenge($pdo,(string)$profile['email_addr'],'password_change',$userId); $_SESSION['password_change_challenge_id']=$cid; $_SESSION['password_change_email']=$profile['email_addr']; $_SESSION['password_change_hash']=password_hash($newPassword,PASSWORD_DEFAULT); $_SESSION['password_change_sent_at']=time(); $_SESSION['flash_success']='A verification code was sent to your email.'; header('Location: profile.php?verify_password=1'); exit; } catch (DomainException $e) { $errors[]=$e->getMessage(); } catch (Throwable $e) { $errors[]='We could not send a verification code. Please try again.'; } }
    } elseif ($action==='verify_password_change') {
        $email=(string)($_SESSION['password_change_email']??''); $cid=(int)($_SESSION['password_change_challenge_id']??0); $code=trim((string)($_POST['otp']??'')); $challenge=null;
        try { if (preg_match('/^\d{6}$/',$code)&&$cid&&$email!=='') $challenge=verify_otp_challenge($pdo,$cid,$email,'password_change',$code); } catch (Throwable $e) { $errors[]='Could not verify the code. Please try again.'; }
        if (!$errors && (!$challenge||(int)$challenge['user_id']!==$userId||empty($_SESSION['password_change_hash']))) $errors[]='The code is incorrect or expired.';
        elseif ($challenge && (int)$challenge['user_id']===$userId) { $pdo->prepare('UPDATE user_credentials SET password=? WHERE user_id=?')->execute([(string)$_SESSION['password_change_hash'],$userId]); unset($_SESSION['password_change_challenge_id'],$_SESSION['password_change_email'],$_SESSION['password_change_hash'],$_SESSION['password_change_sent_at']); $_SESSION['flash_success']='Password changed successfully.'; header('Location: profile.php'); exit; }
    } elseif ($action==='begin_email_change') {
        $newEmail=strtolower(trim((string)($_POST['new_email']??'')));
        if (!verify_account_password($pdo,$userId,(string)($_POST['email_password']??''))) $errors[]='Enter your current password to change your email.';
        if (!filter_var($newEmail,FILTER_VALIDATE_EMAIL)||strlen($newEmail)>255) $errors[]='Enter a valid email address.';
        if (!$errors && strcasecmp($newEmail,(string)$profile['email_addr'])===0) $errors[]='That is already your current email address.';
        if (!$errors) { $dup=$pdo->prepare('SELECT 1 FROM user_credentials WHERE email_addr=?'); $dup->execute([$newEmail]); if ($dup->fetchColumn()) $errors[]='That email address is already registered.'; }
        if (!$errors) { try { $cid=create_otp_challenge($pdo,$newEmail,'email_change',$userId); $_SESSION['email_change_challenge_id']=$cid; $_SESSION['email_change_target']=$newEmail; $_SESSION['email_change_sent_at']=time(); $_SESSION['flash_success']='A verification code was sent to the new email address.'; header('Location: profile.php?verify_email=1'); exit; } catch (DomainException $e) { $errors[]=$e->getMessage(); } catch (Throwable $e) { $errors[]='We could not send a verification code. Please try again.'; } }
    } elseif ($action==='resend_email_change') {
        $target=(string)($_SESSION['email_change_target']??'');
        try { if ($target==='') throw new RuntimeException(); $cid=create_otp_challenge($pdo,$target,'email_change',$userId); $_SESSION['email_change_challenge_id']=$cid; $_SESSION['email_change_sent_at']=time(); $_SESSION['flash_success']='A new verification code was sent.'; header('Location: profile.php?verify_email=1'); exit; } catch (DomainException $e) { $errors[]=$e->getMessage(); } catch (Throwable $e) { $errors[]='Could not resend the code. Try again.'; }
    } elseif ($action==='verify_email_change') {
        $target=(string)($_SESSION['email_change_target']??''); $cid=(int)($_SESSION['email_change_challenge_id']??0); $code=trim((string)($_POST['otp']??'')); $challenge=null;
        try { if (preg_match('/^\d{6}$/',$code)&&$cid&&$target!=='') $challenge=verify_otp_challenge($pdo,$cid,$target,'email_change',$code); } catch (Throwable $e) { $errors[]='Could not verify the code. Please try again.'; }
        if (!$errors && (!$challenge||(int)$challenge['user_id']!==$userId)) $errors[]='The code is incorrect or expired.';
        elseif ($challenge && (int)$challenge['user_id']===$userId) { $dup=$pdo->prepare('SELECT 1 FROM user_credentials WHERE email_addr=? AND user_id<>?'); $dup->execute([$target,$userId]); if ($dup->fetchColumn()) $errors[]='That email address is already registered.'; else { $pdo->prepare('UPDATE user_credentials SET email_addr=? WHERE user_id=?')->execute([$target,$userId]); auth_security_log($pdo,'email_change',$userId,'email_change','completed'); unset($_SESSION['email_change_challenge_id'],$_SESSION['email_change_target'],$_SESSION['email_change_sent_at']); $_SESSION['flash_success']='Email address changed.'; header('Location: profile.php'); exit; } }
    } elseif ($action==='cancel_email_change') { $pdo->prepare('UPDATE auth_otp_challenges SET consumed_at=NOW() WHERE challenge_id=? AND user_id=?')->execute([(int)($_SESSION['email_change_challenge_id']??0),$userId]); unset($_SESSION['email_change_challenge_id'],$_SESSION['email_change_target'],$_SESSION['email_change_sent_at']); $_SESSION['flash_success']='Email change cancelled.'; header('Location: profile.php'); exit;
    } elseif ($action==='begin_deletion') {
        $typed=strtolower(trim((string)($_POST['delete_email']??'')));
        if (!filter_var($typed,FILTER_VALIDATE_EMAIL)||!hash_equals(strtolower((string)$profile['email_addr']),$typed)) $errors[]='Enter the email address on your account.';
        else { try { $cid=create_otp_challenge($pdo,(string)$profile['email_addr'],'account_deletion',$userId); $_SESSION['account_deletion_challenge_id']=$cid; $_SESSION['account_deletion_email']=$profile['email_addr']; $_SESSION['account_deletion_sent_at']=time(); $_SESSION['flash_success']='A six-digit verification code was sent.'; header('Location: profile.php?verify_deletion=1'); exit; } catch (DomainException $e) { $errors[]=$e->getMessage(); } catch (Throwable $e) { $errors[]='We could not send the verification code. Please try again.'; } }
    } elseif ($action==='resend_deletion') {
        $email=(string)($_SESSION['account_deletion_email']??''); try { if ($email==='') throw new RuntimeException(); $cid=create_otp_challenge($pdo,$email,'account_deletion',$userId); $_SESSION['account_deletion_challenge_id']=$cid; $_SESSION['account_deletion_sent_at']=time(); $_SESSION['flash_success']='A new verification code was sent.'; header('Location: profile.php?verify_deletion=1'); exit; } catch (DomainException $e) { $errors[]=$e->getMessage(); } catch (Throwable $e) { $errors[]='Could not resend the code. Try again.'; }
    } elseif ($action==='verify_deletion') {
        $email=(string)($_SESSION['account_deletion_email']??''); $cid=(int)($_SESSION['account_deletion_challenge_id']??0); $code=trim((string)($_POST['otp']??'')); $challenge=null;
        try { if (preg_match('/^\d{6}$/',$code)&&$cid&&$email!=='') $challenge=verify_otp_challenge($pdo,$cid,$email,'account_deletion',$code); } catch (Throwable $e) { $errors[]='Could not verify the code. Please try again.'; }
        if (!$errors && (!$challenge||(int)$challenge['user_id']!==$userId)) $errors[]='The code is incorrect or expired.';
