    } elseif ($action==='cancel_deletion') { $pdo->prepare('UPDATE auth_otp_challenges SET consumed_at=NOW() WHERE challenge_id=? AND user_id=?')->execute([(int)($_SESSION['account_deletion_challenge_id']??0),$userId]); unset($_SESSION['account_deletion_challenge_id'],$_SESSION['account_deletion_email'],$_SESSION['account_deletion_sent_at']); $_SESSION['flash_success']='Account deletion cancelled.'; header('Location: profile.php'); exit;
    }
